userscript.function:

	gridbox.style.height = ($sObject._vp.height() - 66) + 'px';

    var gridTemplate = JSON.parse('{"SELECTED":{"LANGUAGE":"KO","SELECTED_YN":"Y","SCREEN_ID":"SC_SAVE_01","COL_FORMAT":"","HOUSE_CODE":"010","COL_SEQ":"1","TEXT_STYLE":"","NOT_NULL":"0","COL_WIDTH":"40","COL_MAX_LEN":"10000","CONTENTS":"img:[' + window.CONTEXT_NAME + '/resource/plugin/dhtmlx/dhtmlxSuite_v501_pro/skins/material/imgs/dhxgrid_material/item_chk0.gif]","COL_SORT":"","COL_VISIBLE":"true","CODE":"SELECTED","COL_TYPE":"ch","COL_ALIGN":"center","COL_COLOR":"Rcolor","TEMPLATE":"","COL_COMBO":""},"SCREEN_ID":{"LANGUAGE":"KO","SELECTED_YN":"Y","SCREEN_ID":"SC_SAVE_01","COL_FORMAT":"","HOUSE_CODE":"010","COL_SEQ":"2","TEXT_STYLE":"","NOT_NULL":"0","COL_WIDTH":"100","COL_MAX_LEN":"10000","CONTENTS":"화면ID","COL_SORT":"","COL_VISIBLE":"true","CODE":"SCREEN_ID","COL_TYPE":"rotxt","COL_ALIGN":"left","COL_COLOR":"Rcolor","TEMPLATE":"","COL_COMBO":""},"PATH":{"LANGUAGE":"KO","SELECTED_YN":"Y","SCREEN_ID":"SC_SAVE_01","COL_FORMAT":"","HOUSE_CODE":"010","COL_SEQ":"3","TEXT_STYLE":"","NOT_NULL":"0","COL_WIDTH":"*","COL_MAX_LEN":"10000","CONTENTS":"경로","COL_SORT":"","COL_VISIBLE":"true","CODE":"PATH","COL_TYPE":"rotxt","COL_ALIGN":"left","COL_COLOR":"Rcolor","TEMPLATE":"","COL_COMBO":""}}');
    gridObj = $sObject.gridObj = new SepoaDhtmlXGridObject(gridbox, 'gridObj', gridTemplate);
    gridObj._onDnDFlag=false;
    gridObj.setGridDraw();
    gridObj.setSizes();
    gridObj.setDataOutput(dataOutput);
    gridObj.enableColumnMove(false);

    Sepoa.attachEvent('onLoad',function(){
        gridObj.setSizes();
    });

    SUX.attachEvent('onWindowResize',function(){
        gridObj.setSizes();
    });

    gridObj.attachEvent("onRowSelect", function(rid, cid){
        var header = this.getColumnId(cid);
        if(header != "SELECTED"){
            var isChecked = this.cells(rid, 0).isChecked();
            var targetCellIdx = this.getColIndexById("SELECTED");
            if(isChecked){
                this.cells(rid, targetCellIdx).setValue("0")
            } else {
                this.cells(rid, targetCellIdx).setValue("1")
            }
        }
    });

    gridObj.attachEvent("onHeaderClick", function(ind,obj) {
        var selColIdx = this.getColIndexById("SELECTED");
        if(ind === selColIdx){
            const column = gridObj.hdr.rows[1].cells[selColIdx].querySelector('img');
            if(column) {
                const value = gridObj.hdr.rows[1].cells[selColIdx]._selectValue
                if(value === undefined || value == '0') {
                    gridObj.setColumnLabel(selColIdx, 'img:[' + window.CONTEXT_NAME + '/resource/plugin/dhtmlx/dhtmlxSuite_v501_pro/skins/material/imgs/dhxgrid_material/item_chk1.gif]');
                    gridObj.hdr.rows[1].cells[selColIdx]._selectValue = '1';
                    this.checkAll(true);
                } else if(value == '1'){
                    gridObj.setColumnLabel(selColIdx, 'img:[' + window.CONTEXT_NAME + '/resource/plugin/dhtmlx/dhtmlxSuite_v501_pro/skins/material/imgs/dhxgrid_material/item_chk0.gif]');
                    gridObj.hdr.rows[1].cells[selColIdx]._selectValue = '0';
                    this.checkAll(false);
                }
            }
        }
    });

    if(Sepoa.params.initSaveData){
        setRowData();
    }


var initData = Sepoa.params.initSaveData;
var data = {
    rows:[]
};

for(var i in initData){
    data.rows.push({
        id:(parseInt(i)+1), data:["", initData[i].SCREEN_ID, initData[i].PATH]
    });
}
try{
	gridObj.parse(data, "json");
}catch(e){}


var selectedArr = gridObj.getSelectedRows("SELECTED");

if(gridObj.getSelectedRows("SELECTED").length == 0){
    Alert(Sepoa.cache.text.get("SCREEN_BUILDER.SAVE_POPUP_NO_DATA_WARNING"));
    return;
}

var returnObj = {};
for(var i in selectedArr){
    var obj = gridObj._getRowData(selectedArr[i]);
    returnObj[obj.SCREEN_ID] = obj;
}

Sepoa.params.callback(returnObj);
selfObj.close();
